// Studio renders of the six GT27 meshes used on the track. The base paint is
// shared by all editions; the reward card supplies the edition colour.
const partImages = [
  '',
  // HarborV8
  'data:image/webp;base64,',
  // SprintV8
  'data:image/webp;base64,',
  // RoadWheel
  'data:image/webp;base64,',
  // RainWheel
  'data:image/webp;base64,',
  // SprintWing
  'data:image/webp;base64,',
  // AeroWing
  'data:image/webp;base64,',
];

export function rewardArt(model) {
  return Number.isInteger(model) ? partImages[model] || '' : '';
}
